mapper.select:
/*getAuthGroupCount*/
SELECT COUNT(*)
  FROM TM_AUTHXM
 WHERE AUTH_CODE = #{authCode}

mapper.insert:
/*setAuthGroup*/
INSERT INTO TM_AUTHXM (
                         AUTH_CODE
                       , AUTH_NAME
                       , USEE_YSNO
                       , REGI_ADMN
                       , REGI_DATE
                       , UPDT_ADMN
                       , UPDT_DATE
            ) VALUES (  #{authCode}
                      , #{authName}
                      , #{useeYsno}
                      , #{regiAdmn}
                      , SYSTIMESTAMP
                      , #{updtAdmn}
                      , SYSTIMESTAMP
                     )

mapper.update:
/*uptAuthGroup*/
UPDATE TM_AUTHXM
   SET AUTH_NAME = #{authName}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSTIMESTAMP
 WHERE AUTH_CODE = #{authCode}

mapper.insert:
/*setAuthMenu*/
INSERT INTO TB_AUTHMN (
                         AUTH_CODE
                       , MENU_NUMB
                       , SUBX_NUMB
                       , READ_YSNO
                       , WRIT_YSNO
                       , DELT_YSNO
                       , REGI_ADMN
                       , REGI_DATE
                       , UPDT_ADMN
                       , UPDT_DATE
            ) VALUES (  #{authCode}
                      , #{menuNumb}
                      , #{subxNumb}
                      , #{readYsno}
                      , #{writYsno}
                      , #{deltYsno}
                      , #{regiAdmn}
                      , SYSTIMESTAMP
                      , #{updtAdmn}
                      , SYSTIMESTAMP
                     )
